#!/usr/bin/env node
"use strict";

const fs = require("fs");

function readElf(file) {
  const data = fs.readFileSync(file);
  if (data.length < 16 || data[0] !== 0x7f || data[1] !== 0x45 ||
      data[2] !== 0x4c || data[3] !== 0x46) {
    throw new Error("not an ELF file");
  }

  const elfClass = data[4];
  const elfData = data[5];
  if (elfData !== 1 && elfData !== 2) throw new Error("bad ELF data encoding");
  const le = elfData === 1;

  const u16 = (off) => le ? data.readUInt16LE(off) : data.readUInt16BE(off);
  const u32 = (off) => le ? data.readUInt32LE(off) : data.readUInt32BE(off);
  const u64 = (off) => {
    const v = le ? data.readBigUInt64LE(off) : data.readBigUInt64BE(off);
    return Number(v);
  };

  let eType, ePhoff, ePhentsize, ePhnum;

  if (elfClass === 2) {
    eType = u16(16);
    ePhoff = u64(32);
    ePhentsize = u16(54);
    ePhnum = u16(56);
  } else if (elfClass === 1) {
    eType = u16(16);
    ePhoff = u32(28);
    ePhentsize = u16(42);
    ePhnum = u16(44);
  } else {
    throw new Error("unsupported ELF class");
  }

  const PT_LOAD = 1;
  const ET_EXEC = 2;
  const ET_DYN = 3;

  // Position-independent executables are conventionally analysed at this
  // load address; fixed-address executables already carry their addresses.
  const loadBias = eType === ET_DYN ? 0x400000 : 0;

  const segments = [];
  for (let i = 0; i < ePhnum; i++) {
    const off = ePhoff + i * ePhentsize;
    let pType, pOffset, pVaddr, pFilesz;
    if (elfClass === 2) {
      pType = u32(off);
      pOffset = u64(off + 8);
      pVaddr = u64(off + 16);
      pFilesz = u64(off + 32);
    } else {
      pType = u32(off);
      pOffset = u32(off + 4);
      pVaddr = u32(off + 8);
      pFilesz = u32(off + 16);
    }
    if (pType !== PT_LOAD) continue;
    if (pOffset >= data.length) continue;
    const size = Math.min(pFilesz, data.length - pOffset);
    segments.push({ vaddr: pVaddr + loadBias, fileOff: pOffset, size });
  }

  return { data, le, segments };
}

function extract(file) {
  const { data, le, segments } = readElf(file);
  const out = {};

  for (const seg of segments) {
    const words = Math.floor(seg.size / 4);
    for (let i = 0; i < words; i++) {
      const off = seg.fileOff + i * 4;
      const value = le ? data.readUInt32LE(off) : data.readUInt32BE(off);
      out[String(seg.vaddr + i * 4)] = value;
    }
  }

  return out;
}

const file = process.argv[2];
if (!file) {
  process.stderr.write("usage: node extract.js <elf-file>\n");
  process.exit(1);
}

process.stdout.write(JSON.stringify(extract(file)));
process.stdout.write("\n");

